void TeleportToLocation(Vector3 destination)
{
    StartCoroutine(SmoothCameraTransition(destination));
}

IEnumerator SmoothCameraTransition(Vector3 target)
{
    float duration = 0.5f;
    float elapsed = 0f;
    Vector3 start = transform.position;

    while (elapsed < duration)
    {
        transform.position = Vector3.Lerp(start, target, elapsed / duration);
        elapsed += Time.deltaTime;
        yield return null;
    }
}

public void OnSelectEntered(SelectEnterEventArgs args)
{
    grabbed = true;
    rb.isKinematic = true;
}

public void OnSelectExited(SelectExitEventArgs args)
{
    grabbed = false;
    rb.isKinematic = false;
}

void Update()
{
    Vector2 input = new Vector2(Input.GetAxis("Horizontal"), Input.GetAxis("Vertical"));

    targetVelocity = input.normalized * maxSpeed;
    currentVelocity = Vector2.Lerp(currentVelocity, targetVelocity, acceleration * Time.deltaTime);

    transform.position += (Vector3)currentVelocity * Time.deltaTime;
}

void FireWeapon()
{
    Ray ray = new Ray(muzzle.position, muzzle.forward);

    if (Physics.Raycast(ray, out var hit, range))
    {
        SpawnHitEffect(hit.point);
        Damage(hit.collider.gameObject);
    }

    PlayMuzzleFlash();
    PlayRecoil();
}
